import{_ as e,c as t,o as r,a2 as a}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Generators","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview","sidebarGroupTitle":"Generators"},"headers":[],"relativePath":"system-reference/backend/generators/overview.md","filePath":"system-reference/backend/generators/overview.md","lastUpdated":1778363927000}'),o={name:"system-reference/backend/generators/overview.md"},s=a(`<h1 id="generators" tabindex="-1">Generators <a class="header-anchor" href="#generators" aria-label="Permalink to &quot;Generators&quot;">​</a></h1><p>Generators are the scaffolding engine behind Modularous <code>make:*</code> and <code>make:route</code> commands. They produce the full set of PHP and JS files that constitute a new module route, plus the test scaffolding for both the frontend and backend.</p><h2 id="class-hierarchy" tabindex="-1">Class Hierarchy <a class="header-anchor" href="#class-hierarchy" aria-label="Permalink to &quot;Class Hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generator (abstract)                ← NwidartGenerator + ReplacementTrait</span></span>
<span class="line"><span>├── RouteGenerator                  ← full-stack route scaffolding (primary generator)</span></span>
<span class="line"><span>├── StubsGenerator                  ← stub-only regeneration (fix/patch workflow)</span></span>
<span class="line"><span>├── VueTestGenerator                ← Vitest/Jest test file scaffolding</span></span>
<span class="line"><span>└── LaravelTestGenerator            ← PHPUnit test file scaffolding</span></span></code></pre></div><h2 id="generator-reference" tabindex="-1">Generator Reference <a class="header-anchor" href="#generator-reference" aria-label="Permalink to &quot;Generator Reference&quot;">​</a></h2><table><thead><tr><th>Generator</th><th>Source</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="./generator"><code>Generator</code></a></td><td><code>Generators/Generator.php</code></td><td>Abstract base — shared properties, module resolution, config path helpers</td></tr><tr><td><a href="./route-generator"><code>RouteGenerator</code></a></td><td><code>Generators/RouteGenerator.php</code></td><td>Creates the full set of files for a new module route (model, migration, controller, repository, request, translations, permissions)</td></tr><tr><td><a href="./stubs-generator"><code>StubsGenerator</code></a></td><td><code>Generators/StubsGenerator.php</code></td><td>Regenerates stub-based files only; supports selective overwrite via <code>only</code>/<code>except</code> lists</td></tr><tr><td><a href="./vue-test-generator"><code>VueTestGenerator</code></a></td><td><code>Generators/VueTestGenerator.php</code></td><td>Scaffolds a Vitest/Jest test file for a Vue component, composable, utility, or store</td></tr><tr><td><a href="./laravel-test-generator"><code>LaravelTestGenerator</code></a></td><td><code>Generators/LaravelTestGenerator.php</code></td><td>Scaffolds a PHPUnit Unit or Feature test file</td></tr></tbody></table><h2 id="how-generators-are-invoked" tabindex="-1">How Generators Are Invoked <a class="header-anchor" href="#how-generators-are-invoked" aria-label="Permalink to &quot;How Generators Are Invoked&quot;">​</a></h2><p>Generators are not called directly in application code — they are orchestrated by Artisan commands:</p><table><thead><tr><th>Command</th><th>Generator</th></tr></thead><tbody><tr><td><code>modularous:make:route</code></td><td><code>RouteGenerator</code></td></tr><tr><td><code>modularous:fix:route</code></td><td><code>RouteGenerator</code> (with <code>--fix</code>)</td></tr><tr><td><code>modularous:make:stubs</code></td><td><code>StubsGenerator</code></td></tr><tr><td><code>modularous:make:test:vue</code></td><td><code>VueTestGenerator</code></td></tr><tr><td><code>modularous:make:test:laravel</code></td><td><code>LaravelTestGenerator</code></td></tr></tbody></table>`,9),d=[s];function n(c,i,l,h,p,u){return r(),t("div",null,d)}const m=e(o,[["render",n]]);export{b as __pageData,m as default};
